class Solution:
    def romanToInt(self, s: str) -> int:
        # 1. Map each Roman numeral to its integer value
        roman_map = {
            'I': 1,
            'V': 5,
            'X': 10,
            'L': 50,
            'C': 100,
            'D': 500,
            'M': 1000
        }

        total = 0

        # 2. Iterate through the string
        for i in range(len(s)):
            # If the current numeral is less than the NEXT numeral, subtract it
            if i + 1 < len(s) and roman_map[s[i]] < roman_map[s[i + 1]]:
                total -= roman_map[s[i]]
            # Otherwise, just add it to the total
            else:
                total += roman_map[s[i]]

        return total

class Solution(object):
    def threeSum(self, nums):
        nums.sort()
        res = []
        for i in range(len(nums)):
            if i == 0 or nums[i-1] != nums[i]:
                left = i+1
                right = len(nums) - 1
                while left < right:
                    sumThree = nums[i] + nums[left] + nums[right]
                    if sumThree == 0:
                        res.append([nums[i],nums[left],nums[right]])
                        left += 1
                        while left<right and nums[left] == nums[left-1]:
                            left += 1
                    elif sumThree < 0:
                        left += 1
                    else:
                        right -= 1
        return res

class Solution:
    def threeSumClosest(self, nums: List[int], target: int) -> int:
        closest = float('inf')
        nums.sort() #O(N*LogN)
        n = len(nums)
        for i in range(n-2): #O(N)
            left, right = i + 1, n - 1 
            while left < right : #O(N^2)
                total = nums[i] + nums[left] + nums[right]
                if abs(total - target ) < abs(closest - target):
                    closest = total

                if total < target:
                    left += 1
                elif total > target:
                    right -= 1 
                else:
                    return target

        return closest

