        n = len(costs)
        total_cost = 0
        for i in range(n//2):
            total_cost += costs[i][0]
        for i in range(n//2,n):
            total_cost += costs[i][1]

        return total_cost

class Solution(object):
    def removeDuplicates(self, s):
        # Use a stack to remove adjacent duplicates in one pass
        stack = []
        for ch in s:
            if stack and stack[-1] == ch:
                stack.pop()
            else:
                stack.append(ch)
        return ''.join(stack)

