class Solution:
    def pivotArray(self, nums: List[int], pivot: int) -> List[int]:
        smaller = []
        equal = []
        larger = []
        for num in nums :
            if num < pivot :
                smaller.append(num)
            elif num == pivot :
                equal.append(num)
            else:
                larger.append(num)
        return smaller + equal + larger

