class Solution:
    def earliestFinishTime(self, landStartTime: List[int], landDuration: List[int], waterStartTime: List[int], waterDuration: List[int]) -> int:
        minLand1 = float('inf')
        for i in range(len(landStartTime)):
            minLand1 = min(minLand1, landStartTime[i] + landDuration[i])

        result1 = float('inf')
        for i in range(len(waterStartTime)):
            waterStart = max(minLand1, waterStartTime[i])
            result1 = min(result1, waterStart + waterDuration[i])

        minWater2 = float('inf')
        for i in range(len(waterStartTime)):
            minWater2 = min(minWater2, waterStartTime[i] + waterDuration[i])

        result2 = float('inf')
        for i in range(len(landStartTime)):
            landStart = max(minWater2, landStartTime[i])
            result2 = min(result2, landStart + landDuration[i])

        return min(result1, result2)

class Solution:
    def gcdOfOddEvenSums(self, n: int) -> int:
        import math
        sumOdd = n*n
        sumEven = n * (n+1)
        return math.gcd(sumOdd,sumEven)

class Solution:
    def recoverOrder(self, order: List[int], friends: List[int]) -> List[int]:
        res_list = set(friends)
        res = []
        for id in order:
            if id in res_list:
                res.append(id)
        return res

class Solution:
    def sumDivisibleByK(self, nums: List[int], k: int) -> int:
        result = 0
        seen = Counter(nums)
        for value, count in seen.items():
            if count % k == 0:
                result += (value * count)
        return result

class Solution:
    def minMoves(self, nums: List[int]) -> int:
        result = 0
        maximum = max(nums)

        for num in nums:
            result += maximum - num

        return result

class Solution:
    def sumAndMultiply(self, n: int) -> int:
        n_str = str(n)

        x_str = "".join(digit for digit in n_str if digit != '0')

        if not x_str:
            x = 0
            sum_of_digits = 0
        else:
            x = int(x_str)
            sum_of_digits = sum(int(digit) for digit in x_str)

        result = x * sum_of_digits
        return result

class Solution:
    def maxBalancedSubarray(self, nums: List[int]) -> int:
        n = nums
        m = {(0, 0): 0}
        l, x, b = 0, 0, 0
        N = len(n)

        for k in range(1, N + 1):
            num = n[k - 1]
            x ^= num
            b += 1 if num % 2 else -1

            s = (x, b)

            if s in m:
                l = max(l, k - m[s])
            else:
                m[s] = k

        return l

class Solution:
    def digitFrequencyScore(self, n: int) -> int:
        frequency = {}
        for ch in str(n):
            digits = int(ch)
            frequency[digits] = frequency.get(digits,0) + 1
        score = 0
        for digit, count in frequency.items():
            score += digit * count
        return score
